// Builds the two README diagrams: hero.svg and schema.svg.
// Node built-ins only. Same script, same bytes: no clock, no randomness, no network.
// Every number on the hero comes from the seed 7 studio generated by lib/seed.mjs.
// Run from the repo root: node docs/img/make.mjs

import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DEFAULT_SEED, generateStudio } from '../../lib/seed.mjs';

const OUT = dirname(fileURLToPath(import.meta.url));

const NAVY = '#001B3B';
const SAND = '#EDE7DC';
const TERRACOTTA = '#8C5348';
const OLIVE = '#59591D';
const HEAD = '#F2EDE2';
const SUB = '#D8D3CA';
const SERIF = "Georgia, 'Playfair Display', serif";
const SANS = "-apple-system, 'Helvetica Neue', Helvetica, Arial, sans-serif";

const W = 1200;

const esc = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const money = (value) => Number(value).toLocaleString('en-US', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

function text(x, y, value, options = {}) {
  const attrs = [
    `x="${x}"`,
    `y="${y}"`,
    `font-family="${options.serif ? SERIF : SANS}"`,
    `font-size="${options.size || 16}"`,
  ];
  if (options.bold) attrs.push('font-weight="700"');
  if (options.anchor) attrs.push(`text-anchor="${options.anchor}"`);
  attrs.push(`fill="${options.fill || SUB}"`);
  return `<text ${attrs.join(' ')}>${esc(value)}</text>`;
}

function rect(x, y, width, height, options = {}) {
  const attrs = [`x="${x}"`, `y="${y}"`, `width="${width}"`, `height="${height}"`];
  if (options.rx) attrs.push(`rx="${options.rx}"`);
  attrs.push(`fill="${options.fill || 'none'}"`);
  if (options.stroke) attrs.push(`stroke="${options.stroke}"`, 'stroke-width="1"');
  return `<rect ${attrs.join(' ')}/>`;
}

// A straight arrow built from two filled polygons, so every renderer draws it the same.
function arrow(x1, y1, x2, y2, options = {}) {
  const fill = options.fill || SAND;
  const head = options.head || 10;
  const shaft = options.shaft || 2;
  const length = Math.hypot(x2 - x1, y2 - y1);
  const ux = (x2 - x1) / length;
  const uy = (y2 - y1) / length;
  const bx = x2 - ux * head;
  const by = y2 - uy * head;
  const nx = -uy;
  const ny = ux;
  const half = shaft / 2;
  const points = (list) => list.map(([x, y]) => `${x},${y}`).join(' ');
  const body = [
    [x1 + nx * half, y1 + ny * half],
    [bx + nx * half, by + ny * half],
    [bx - nx * half, by - ny * half],
    [x1 - nx * half, y1 - ny * half],
  ];
  const tip = [
    [x2, y2],
    [bx + nx * head * 0.5, by + ny * head * 0.5],
    [bx - nx * head * 0.5, by - ny * head * 0.5],
  ];
  return [
    `<polygon points="${points(body)}" fill="${fill}"/>`,
    `<polygon points="${points(tip)}" fill="${fill}"/>`,
  ].join('');
}

function frame(title, desc, height, body) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${height}" `
    + `viewBox="0 0 ${W} ${height}" role="img">\n`
    + `<title>${esc(title)}</title>\n`
    + `<desc>${esc(desc)}</desc>\n`
    + rect(0, 0, W, height, { fill: NAVY })
    + rect(0.5, 0.5, W - 1, height - 1, { stroke: SAND })
    + body
    + '</svg>\n';
}

function hero(data) {
  const cash = data.closes[0];
  const tiles = [
    { label: 'members', value: String(data.members.length) },
    { label: 'packages sold', value: String(data.packages.length) },
    { label: 'ledger rows', value: String(data.ledger.length) },
    { label: 'classes in four weeks', value: String(data.classes.length) },
    { label: 'bookings', value: String(data.bookings.length) },
  ];

  const parts = [
    text(60, 58, `${data.studio.name}. One seeded studio.`, { serif: true, size: 32, fill: HEAD }),
    text(60, 90, 'Package credits are a signed ledger. The balance is a view over it. '
      + 'The close is signed by the owner.', { size: 16, fill: SUB }),
  ];

  const boxWidth = 200;
  const gap = 25;
  tiles.forEach((tile, index) => {
    const x = 50 + index * (boxWidth + gap);
    parts.push(rect(x, 140, boxWidth, 130, { fill: 'none', stroke: SAND, rx: 6 }));
    parts.push(text(x + boxWidth / 2, 215, tile.value, {
      size: 42, bold: true, fill: HEAD, anchor: 'middle',
    }));
    parts.push(text(x + boxWidth / 2, 248, tile.label, {
      size: 14, fill: SUB, anchor: 'middle',
    }));
    if (index < tiles.length - 1) {
      const from = x + boxWidth + 2;
      parts.push(arrow(from, 205, from + gap - 4, 205, { fill: TERRACOTTA, head: 8, shaft: 2 }));
    }
  });

  const closeY = 315;
  parts.push(rect(50, closeY, W - 100, 85, { fill: 'none', stroke: SAND, rx: 6 }));
  parts.push(text(72, closeY + 34, `Cash close, ${cash.day}`, { size: 16, bold: true, fill: HEAD }));
  parts.push(text(72, closeY + 62, 'expected', { size: 13, fill: SUB }));
  parts.push(text(160, closeY + 64, money(cash.expected), { size: 26, bold: true, fill: HEAD }));
  parts.push(text(330, closeY + 62, 'counted', { size: 13, fill: SUB }));
  parts.push(text(410, closeY + 64, money(cash.counted), { size: 26, bold: true, fill: HEAD }));
  parts.push(text(580, closeY + 62, 'difference', { size: 13, fill: SUB }));
  parts.push(text(675, closeY + 64, money(cash.difference), { size: 26, bold: true, fill: OLIVE }));
  parts.push(text(W - 72, closeY + 44, 'signed off by the owner', {
    size: 15, fill: SUB, anchor: 'end',
  }));
  parts.push(text(W - 72, closeY + 66, 'one closed day in the seed', {
    size: 13, fill: SUB, anchor: 'end',
  }));

  parts.push(text(60, 428, `Seed ${data.studio.seed}. Every run of the seed writes this same `
    + 'studio, byte for byte.', { size: 13, fill: SUB }));

  return frame(
    'Cedarline Studio: 60 members, 188 ledger rows, 126 bookings and one signed cash close',
    'A diagram of the seeded studio: 60 members, 60 packages, 188 ledger rows, 24 classes, '
    + '126 bookings and one closed day with expected, counted and difference all at 1,347.00.',
    460,
    parts.join('\n'),
  );
}

function box(x, y, width, height, title, lines, accent) {
  return [
    rect(x, y, width, height, { fill: 'none', stroke: accent || SAND, rx: 6 }),
    text(x + 16, y + 30, title, { size: 18, bold: true, fill: HEAD }),
    ...lines.map((line, index) => text(x + 16, y + 54 + index * 19, line, { size: 13, fill: SUB })),
  ].join('');
}

function schema() {
  const col = [50, 330, 610];
  const row = [110, 250, 390];
  const bw = 250;
  const bh = 100;
  const parts = [
    text(60, 52, 'The tables, the ledger view, and the write paths for credits', {
      serif: true, size: 28, fill: HEAD,
    }),
    text(60, 82, 'Row level security is on for every table. Only the three functions write the ledger.', {
      size: 15, fill: SUB,
    }),
    box(col[0], row[0], bw, bh, 'members', ['id, full_name, email'], SAND),
    box(col[1], row[0], bw, bh, 'bookings', ['member_id, class_id, package_id', 'cancelled_at (cancel_booking)'], SAND),
    box(col[2], row[0], bw, bh, 'classes', ['instructor_id, starts_at, capacity'], SAND),
    box(col[0], row[1], bw, bh, 'packages', ['member_id, credits, price'], SAND),
    box(col[1], row[1], bw, bh, 'credit_ledger', ['kind, credits (signed), occurred_at'], TERRACOTTA),
    box(col[2], row[1], bw, bh, 'member_credits', ['member_id, package_id, remaining'], OLIVE),
    box(col[0], row[2], bw, bh, 'payments', ['amount, method, paid_at'], SAND),
    box(col[1], row[2], bw, bh, 'cash_close', ['expected, counted, difference', 'signed_off_by'], SAND),
    box(col[2], row[2], bw, bh, 'staff', ['role: owner, front_desk, instructor'], SAND),

    arrow(col[0] + 100, row[0] + bh, col[0] + 100, row[1] - 4, { fill: TERRACOTTA }),
    arrow(col[1] + 120, row[0] + bh, col[1] + 120, row[1] - 4, { fill: TERRACOTTA }),
    arrow(col[0] + bw + 4, row[0] + 40, col[1] - 4, row[0] + 40, { fill: TERRACOTTA }),
    arrow(col[2] - 4, row[0] + 40, col[1] + bw + 4, row[0] + 40, { fill: TERRACOTTA }),
    arrow(col[0] + bw + 4, row[1] + 40, col[1] - 4, row[1] + 40, { fill: TERRACOTTA }),
    arrow(col[1] + bw + 4, row[1] + 40, col[2] - 4, row[1] + 40, { fill: OLIVE }),
    arrow(col[0] + bw + 4, row[2] + 40, col[1] - 4, row[2] + 40, { fill: TERRACOTTA }),
    arrow(col[1] + bw + 4, row[2] + 40, col[2] - 4, row[2] + 40, { fill: TERRACOTTA }),
  ];

  const notesX = 890;
  parts.push(rect(notesX, row[0], 260, 380, { fill: 'none', stroke: SAND, rx: 6 }));
  parts.push(text(notesX + 16, row[0] + 30, 'book_class(member, class)', {
    size: 16, bold: true, fill: HEAD,
  }));
  parts.push(text(notesX + 16, row[0] + 54, 'One transaction.', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 76, 'Lock the member and the class.', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 98, 'Refuse a full class or no credit.', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 120, 'Take one credit, write the booking', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 142, 'and the use row together.', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 170, 'Expired packages cannot pay.', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 192, 'Owner runs expire_credits.', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 222, 'The ledger is append only.', {
    size: 14, bold: true, fill: TERRACOTTA,
  }));
  parts.push(text(notesX + 16, row[0] + 244, 'No UPDATE. No DELETE.', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 266, 'No balance stored on a package.', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 300, 'The close', { size: 14, bold: true, fill: HEAD }));
  parts.push(text(notesX + 16, row[0] + 322, 'A difference needs a note and', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 344, 'an owner sign-off. A closed day', { size: 13, fill: SUB }));
  parts.push(text(notesX + 16, row[0] + 366, 'is final for every role.', { size: 13, fill: SUB }));

  return frame(
    'The schema: eight tables, a credits view and the booking function',
    'Nine boxes: members, bookings, classes, packages, credit_ledger, member_credits, payments, '
    + 'cash_close and staff, with the foreign keys between them and notes on book_class, expiry and the close.',
    520,
    parts.join('\n'),
  );
}

const data = generateStudio(DEFAULT_SEED);
writeFileSync(join(OUT, 'hero.svg'), hero(data), 'utf8');
writeFileSync(join(OUT, 'schema.svg'), schema(), 'utf8');
console.log('wrote docs/img/hero.svg and docs/img/schema.svg');
